<?php $title='Reservations'; ?>
<div class="page-head"><div class="eyebrow">Queue <i></i> <?= count($rows) ?> holds</div><h1>Reservations</h1><p>Pending → notified (24h) → fulfilled/cancelled. Return sweep notifies next.</p></div>
<div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Book</th><th>Status</th><th>Since</th><th>Expires</th><th></th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><b><?= e($r['name']) ?></b><br><span class="mono" style="font-size:11px; color:var(--slate)"><?= e($r['enrollment_no'] ?? '') ?></span></td><td><?= e($r['title']) ?></td><td><span class="pill <?= $r['status']==='pending'?'pill-amber':($r['status']==='notified'?'pill-green':($r['status']==='fulfilled'?'pill-green':'pill-slate')) ?>"><span class="pill-dot"></span><?= e($r['status']) ?></span></td><td class="mono" style="font-size:12px"><?= e($r['reservation_date']) ?></td><td class="mono" style="font-size:12px"><?= e($r['expires_at'] ?? '—') ?></td><td style="display:flex; gap:6px"><?php if($r['status']!=='cancelled' && $r['status']!=='fulfilled'): ?><form method="post" action="/reservations/<?= (int)$r['id'] ?>/cancel"><button class="btn btn-ghost btn-small">Cancel</button></form><?php endif; ?><?php if($r['status']==='notified'): ?><form method="post" action="/reservations/<?= (int)$r['id'] ?>/fulfill"><button class="btn btn-primary btn-small">Fulfill</button></form><?php endif; ?></td></tr><?php endforeach; if(empty($rows)): ?><tr><td colspan="6" style="text-align:center; color:var(--slate)">No reservations.</td></tr><?php endif; ?>
</tbody></table></div>
